const getIssueWorkflowConsistency = `-- name: GetIssueWorkflowConsistency :one
SELECT
    CASE WHEN w.default_issue_workflow_id IS NULL THEN 1 ELSE 0 END::bigint AS workspaces_without_default,
    (
        SELECT count(*)::bigint
        FROM issue AS i
        WHERE i.workspace_id = w.id
          AND (i.workflow_id IS NULL OR i.workflow_status_id IS NULL)
    ) AS issues_without_binding,
    (
        SELECT count(*)::bigint
        FROM issue AS i
        LEFT JOIN issue_workflow_status AS s
          ON s.id = i.workflow_status_id
         AND s.workflow_id = i.workflow_id
         AND s.workspace_id = i.workspace_id
        WHERE i.workspace_id = w.id
          AND i.workflow_status_id IS NOT NULL
          AND (s.id IS NULL OR COALESCE(s.legacy_status_key, CASE s.phase
                  WHEN 'backlog' THEN 'backlog'
                  WHEN 'unstarted' THEN 'todo'
                  WHEN 'completed' THEN 'done'
                  WHEN 'cancelled' THEN 'cancelled'
                  ELSE 'in_progress'
              END) IS DISTINCT FROM i.status)
    ) AS issues_with_status_mismatch,
    (
        SELECT count(*)::bigint
        FROM issue AS i
        LEFT JOIN issue_transition AS t
          ON t.id = i.last_transition_id
         AND t.workspace_id = i.workspace_id
        WHERE i.workspace_id = w.id
          AND (
              i.last_transition_id IS NULL OR
              t.id IS NULL OR
              t.issue_id IS DISTINCT FROM i.id OR
              t.workflow_id IS DISTINCT FROM i.workflow_id OR
              t.to_status_id IS DISTINCT FROM i.workflow_status_id OR
              t.issue_revision_after > i.revision
          )
    ) AS issues_with_transition_mismatch
FROM workspace AS w
WHERE w.id = $1
`

type GetIssueWorkflowConsistencyRow struct {
	WorkspacesWithoutDefault     int64 `json:"workspaces_without_default"`
	IssuesWithoutBinding         int64 `json:"issues_without_binding"`
	IssuesWithStatusMismatch     int64 `json:"issues_with_status_mismatch"`
	IssuesWithTransitionMismatch int64 `json:"issues_with_transition_mismatch"`
}

func (q *Queries) GetIssueWorkflowConsistency(ctx context.Context, id pgtype.UUID) (GetIssueWorkflowConsistencyRow, error) {
	row := q.db.QueryRow(ctx, getIssueWorkflowConsistency, id)
	var i GetIssueWorkflowConsistencyRow
	err := row.Scan(
		&i.WorkspacesWithoutDefault,
		&i.IssuesWithoutBinding,
		&i.IssuesWithStatusMismatch,
		&i.IssuesWithTransitionMismatch,
	)
	return i, err
}

